use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn run_interactive_mode (kb_file : & str , target_dir : & str) -> Result < () > { println ! ("🎯 Interactive SPARQL-to-AST Mode") ; println ! ("=================================") ; let mut generator = SparqlProbeGenerator :: new () ; generator . load_rdf_data (kb_file) ? ; loop { println ! ("\n🔍 Available commands:") ; println ! ("  1. Generate top N complex function probes") ; println ! ("  2. Generate complexity threshold probes") ; println ! ("  3. Apply generated probes to {}" , target_dir) ; println ! ("  4. Show current probe statistics") ; println ! ("  5. Exit") ; print ! ("\nEnter choice (1-5): ") ; std :: io :: Write :: flush (& mut std :: io :: stdout ()) ? ; let mut input = String :: new () ; std :: io :: stdin () . read_line (& mut input) ? ; match input . trim () { "1" => { print ! ("Enter number of top complex functions (default 10): ") ; std :: io :: Write :: flush (& mut std :: io :: stdout ()) ? ; let mut n_input = String :: new () ; std :: io :: stdin () . read_line (& mut n_input) ? ; let n = n_input . trim () . parse () . unwrap_or (10) ; let probes = generator . generate_complexity_wrapper_probes (n) ; let json = serde_json :: to_string_pretty (& probes) ? ; std :: fs :: write ("interactive_probes.json" , json) ? ; println ! ("✅ Generated {} probes for top {} complex functions" , probes . len () , n) ; } "2" => { print ! ("Enter complexity threshold (default 8.0): ") ; std :: io :: Write :: flush (& mut std :: io :: stdout ()) ? ; let mut threshold_input = String :: new () ; std :: io :: stdin () . read_line (& mut threshold_input) ? ; let threshold = threshold_input . trim () . parse () . unwrap_or (8.0) ; generate_probes_from_sparql (kb_file , 0 , "interactive_probes.json" , threshold) ? ; } "3" => { apply_sparql_probes (target_dir , "interactive_probes.json" , true) ? ; } "4" => { if let Ok (content) = std :: fs :: read_to_string ("interactive_probes.json") { if let Ok (probes) = serde_json :: from_str :: < Vec < split_decls_rs :: ast_reflector :: AstProbe > > (& content) { println ! ("📊 Current probe statistics:") ; println ! ("   Total probes: {}" , probes . len ()) ; println ! ("   Enabled probes: {}" , probes . iter () . filter (| p | p . enabled) . count ()) ; let mut action_counts = std :: collections :: HashMap :: new () ; for probe in & probes { let action_type = match & probe . action { split_decls_rs :: ast_reflector :: ProbeAction :: Log { .. } => "Log" , split_decls_rs :: ast_reflector :: ProbeAction :: AddAttribute { .. } => "AddAttribute" , split_decls_rs :: ast_reflector :: ProbeAction :: WrapFunction { .. } => "WrapFunction" , split_decls_rs :: ast_reflector :: ProbeAction :: InjectCode { .. } => "InjectCode" , split_decls_rs :: ast_reflector :: ProbeAction :: Transform { .. } => "Transform" , split_decls_rs :: ast_reflector :: ProbeAction :: Collect { .. } => "Collect" , split_decls_rs :: ast_reflector :: ProbeAction :: Enhance { .. } => "Enhance" , } ; * action_counts . entry (action_type) . or_insert (0) += 1 ; } println ! ("   Action breakdown:") ; for (action , count) in action_counts { println ! ("     • {}: {}" , action , count) ; } } } else { println ! ("❌ No probes generated yet") ; } } "5" => { println ! ("👋 Goodbye!") ; break ; } _ => { println ! ("❌ Invalid choice, please enter 1-5") ; } } } Ok (()) }